  var RED = C.red, REDS = "#B8323A", LEAF = "#7CC46A", LEAFS = "#4F9A52", MINT = "#7FE3C4", MINTS = "#43B894", WATER = "#5DBDEB";
  /* "2x" drawn in ink, never as text: the stroke under it is the outline */
